{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto
{\pard \ql \f0 \sa180 \li0 \fi0 Toggles item mute (ignoring groups) based on the track under the mouse cursor. Targeting priority (all scoped to the mouse track): 1) If Razor Edit exists on the mouse track: WHOLE items on the mouse track touched by Razor. 2) Else if Time Selection exists: WHOLE items on the mouse track that intersect the TS. 3) Else if any selected items exist on the mouse track: those items. 4) Else: the single item under the mouse cursor.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Majority rule:\par}
{\pard \ql \f0 \sa60 \li360 \fi-360 \bullet \tx360\tab If most targeted items are muted, unmute all; if most are unmuted, mute all.\par}
{\pard \ql \f0 \sa60 \li360 \fi-360 \bullet \tx360\tab Tie-breaker: mute all (deterministic).\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Notes:\par}
{\pard \ql \f0 \sa60 \li360 \fi-360 \bullet \tx360\tab Ignores grouping by writing item mute flag directly (B_MUTE).\par}
{\pard \ql \f0 \sa60 \li360 \fi-360 \bullet \tx360\tab Works with locked items; doesn\u8217?t require SWS.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
