{\pard \ql \f0 \sa180 \li0 \fi0 \b \fs28 Removes fades. Loop Source state is LEFT UNCHANGED. Works only within the same track.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
